%% Errendimendua nola aldatzen den foku beroaren eta hotzaren arteko tenperatura diferentziaren araberafunction y=grafikoa4(a,b,Q,W,Tdif,izena,f1) n=300; x=linspace(a,b,n+1); F=(W./Q)*100; max(F)   figure(f1)     plot(x,F)      xlabel("I (A)")      ylabel("Rendimiento (%)")      title("Valores de rendimiento termoelectrico en unos amperajes concretos")      legend(izena,'Location','southoutside')      legend('boxoff')      grid on         print(figure(f1),'Rendimiento')endfunction